B.QQ=new A.cT("fc_dgs_mat_10","\u0130ki Kare Fark\u0131 ve Tam Kare","\u0130ki kare fark\u0131: a\xb2 - b\xb2 = (a - b)(a + b). Tam kare: (a + b)\xb2 = a\xb2 + 2ab + b\xb2, (a - b)\xb2 = a\xb2 - 2ab + b\xb2.","DGS Temel Matematik","\xd6zde\u015flikler","101\xb2 - 99\xb2 = (101 - 99)(101 + 99) = 2 \xd7 200 = 400.","DGS'de a\xb2 + b\xb2 soruldu\u011funda (a + b)\xb2 - 2ab a\xe7\u0131l\u0131m\u0131 en \xe7ok kullan\u0131lan pratik yoldur!")
B.QR=new A.cT("fc_dgs_geo_2","Muhte\u015fem \xdc\xe7l\xfc Kural\u0131","Bir dik \xfc\xe7gende 90\xb0'lik a\xe7\u0131dan hipoten\xfcse \xe7izilen kenarortay, ay\u0131rd\u0131\u011f\u0131 par\xe7alara e\u015fittir (|AD| = |BD| = |DC|).","DGS Geometri","\xdc\xe7gende Alan","Hipoten\xfcs uzunlu\u011fu 20 cm ise kenarortay uzunlu\u011fu 10 cm olur.","Soruda dik \xfc\xe7gen ve hipoten\xfcse inen kenarortay varsa teredd\xfcts\xfcz e\u015fitlik i\u015faretini koy!")
B.QS=new A.cT("fc_dgs_tr_2","D\xfc\u015f\xfcncenin Ak\u0131\u015f\u0131n\u0131 Bozan C\xfcmle","Paragrafta ele al\u0131nan konunun d\u0131\u015f\u0131na \xe7\u0131kan veya konunun bamba\u015fka bir y\xf6n\xfcne aniden ge\xe7i\u015f yapan c\xfcmle ak\u0131\u015f\u0131 bozar.","DGS T\xfcrk\xe7e","Paragraf Yap\u0131s\u0131","Bir yazar\u0131n \xfcslubundan bahsederken araya giren yazar\u0131n \xe7ocukluk y\u0131llar\u0131 \xe7ok zor ge\xe7mi\u015ftir c\xfcmlesi ak\u0131\u015f\u0131 bozar.","Ak\u0131\u015f\u0131 bozan c\xfcmleyi paragraftan \xe7\u0131kard\u0131\u011f\u0131nda \xf6nceki ve sonraki c\xfcmle birbirine anlamca kusursuz ba\u011flanmal\u0131d\u0131r!")
B.QT=new A.cT("fc_dgs_prob_4","Maliyet ve Sat\u0131\u015f Fiyat\u0131 Form\xfclleri","Maliyet = 100x se\xe7ilir. %20 karl\u0131 sat\u0131\u015f = 120x, %15 zararl\u0131 sat\u0131\u015f = 85x. \u0130ndirim daima o anki etiket fiyat\u0131 \xfczerinden hesaplan\u0131r.","DGS Problemler","Y\xfczde & K\xe2r-Zarar","100 TL maliyetli \xfcr\xfcne %20 kar konursa 120 TL olur. 120 TL \xfczerinden %10 indirim yap\u0131l\u0131rsa 120 - 12 = 108 TL'ye sat\u0131l\u0131r (Net %8 kar).","Y\xfczde sorular\u0131nda bilinmeyene x demek yerine 100x demek hesaplamay\u0131 3 kat h\u0131zland\u0131r\u0131r!")
B.QU=new A.cT("fc_dgs_geo_4","Dairenin Alan\u0131 ve \xc7evresi","\xc7evre = 2\u03c0r. Alan = \u03c0r\xb2. \u03b1 derecelik daire dilimi alan\u0131 = \u03c0r\xb2 \xd7 (\u03b1 / 360).","DGS Geometri","Daire ve \xc7ember","Yar\u0131\xe7ap\u0131 6 cm olan 60\xb0'lik daire diliminin alan\u0131: \u03c0 \xd7 36 \xd7 (60/360) = 6\u03c0 cm\xb2.","\xc7ap\u0131 g\xf6ren \xe7evre a\xe7\u0131 daima 90\xb0'dir!")
B.QV=new A.cT("fc_dgs_tr_4","Gereksiz S\xf6zc\xfck Kullan\u0131m\u0131","Ayn\u0131 anlama gelen s\xf6zc\xfcklerin veya e\u015f anlaml\u0131 kelimelerin bir arada kullan\u0131lmas\u0131 anlat\u0131m bozuklu\u011funa yol a\xe7ar.","DGS T\xfcrk\xe7e","Anlat\u0131m Bozukluklar\u0131","Bari hi\xe7 olmazsa sen gel c\xfcmlesinde bari ve hi\xe7 olmazsa ayn\u0131 anlamdad\u0131r, biri gereksizdir.","Bir s\xf6zc\xfck c\xfcmleden \xe7\u0131kar\u0131ld\u0131\u011f\u0131nda anlamda daralma veya bozulma olmuyorsa o s\xf6zc\xfck gereksizdir!")
B.QW=new A.cT("fc_dgs_say_3","K\xfcp A\xe7\u0131l\u0131mlar\u0131 ve Kar\u015f\u0131l\u0131kl\u0131 Y\xfczler","Bir k\xfcp a\xe7\u0131n\u0131m\u0131nda aralar\u0131nda tam 1 kare bulunan y\xfczler k\xfcp kapat\u0131ld\u0131\u011f\u0131nda birbirine PARALEL (kar\u015f\u0131 kar\u015f\u0131ya) gelir.","DGS Say\u0131sal Mant\u0131k","\u015eekil Yetene\u011fi","Yan yana duran y\xfczler asla kar\u015f\u0131 kar\u015f\u0131ya gelemez, kom\u015fu y\xfcz olurlar.","DGS k\xfcp sorular\u0131nda kar\u015f\u0131 kar\u015f\u0131ya gelen y\xfcz \xe7iftlerini hemen e\u015fle\u015ftirip \u015f\u0131klar\u0131 buna g\xf6re ele!")
B.QX=new A.cT("fc_dgs_geo_1","Pisagor ve \xd6zel Kenar \xdc\xe7genleri","a\xb2 + b\xb2 = c\xb2 (Hipoten\xfcs en uzun kenard\u0131r). \xd6zel kenarlar: 3-4-5, 5-12-13, 8-15-17, 7-24-25 ve katlar\u0131.","DGS Geometri","\xd6zel Dik \xdc\xe7genler","Dik kenarlar\u0131 6 ve 8 olan \xfc\xe7genin hipoten\xfcs\xfc 3-4-5'in 2 kat\u0131ndan 10'dur.","30-60-90 \xfc\xe7geninde 30\xb0 kar\u015f\u0131s\u0131 a ise 90\xb0 kar\u015f\u0131s\u0131 2a, 60\xb0 kar\u015f\u0131s\u0131 a\u221a3 olur!")
B.QY=new A.cT("fc_dgs_mat_6","Bile\u015fik B\xf6l\xfcnebilme Kurallar\u0131","Bir say\u0131 aralar\u0131nda asal iki say\u0131ya tam b\xf6l\xfcn\xfcyorsa \xe7arp\u0131mlar\u0131na da tam b\xf6l\xfcn\xfcr. 6 i\xe7in (2 ve 3), 12 i\xe7in (3 ve 4), 15 i\xe7in (3 ve 5), 36 i\xe7in (4 ve 9), 45 i\xe7in (5 ve 9).","DGS Temel Matematik","B\xf6l\xfcnebilme","36'ya tam b\xf6l\xfcnen say\u0131 hem 4'e (son iki basamak) hem 9'a (rakamlar toplam\u0131) b\xf6l\xfcnmelidir.","\u0130ncelemeye daima son basama\u011f\u0131 belirleyen kuraldan (2, 5 veya 4) ba\u015flan\u0131r, ard\u0131ndan rakam toplam\u0131 (3, 9) incelenir!")
B.QZ=new A.cT("fc_dgs_mat_4","n! ve Sondan S\u0131f\u0131r Say\u0131s\u0131","n! say\u0131s\u0131n\u0131n sondaki s\u0131f\u0131r say\u0131s\u0131n\u0131 bulmak i\xe7in n say\u0131s\u0131 s\xfcrekli 5'e b\xf6l\xfcn\xfcr ve b\xf6l\xfcmler toplan\u0131r.","DGS Temel Matematik","Fakt\xf6riyel","60! sondan ka\xe7 basama\u011f\u0131 s\u0131f\u0131rd\u0131r? 60/5 = 12, 12/5 = 2. Toplam = 12 + 2 = 14 s\u0131f\u0131r.","Fakt\xf6riyel sadele\u015ftirmelerinde b\xfcy\xfck fakt\xf6riyel daima k\xfc\xe7\xfck olan\u0131n cinsinden a\xe7\u0131l\u0131r: (n+1)! = (n+1) \xd7 n!")
B.R_=new A.cT("fc_dgs_mat_3","Terim Say\u0131s\u0131 ve Toplam Form\xfcl\xfc","Terim Say\u0131s\u0131 = [(Son Terim - \u0130lk Terim) / Art\u0131\u015f Miktar\u0131] + 1. Toplam = Terim Say\u0131s\u0131 \xd7 [(Son Terim + \u0130lk Terim) / 2] (Ortanca Terim).","DGS Temel Matematik","Ard\u0131\u015f\u0131k Say\u0131lar","3 + 7 + 11 + ... + 39 i\xe7in TS = [(39 - 3)/4] + 1 = 10 terim. Toplam = 10 \xd7 [(39 + 3)/2] = 210.","DGS'de ard\u0131\u015f\u0131k tek veya \xe7ift say\u0131lar iki\u015fer iki\u015fer (n, n+2, n+4...) artar, art\u0131\u015f miktar\u0131 2 al\u0131n\u0131r!")
B.R0=new A.cT("fc_dgs_soz_1","Sabit De\u011fi\u015fken Eksen Kural\u0131","S\xf6zel mant\u0131kta ki\u015fi say\u0131s\u0131 fazla, g\xfcnler/katlar/s\u0131ralar az ve sabitse; tabloya daima az ve sabit olan eksen yaz\u0131l\u0131r.","DGS S\xf6zel Mant\u0131k","Tablo Kurma","Ali, Berk, Can, Deniz, Ece haftan\u0131n 5 g\xfcn\xfcnde n\xf6bet tutuyorsa tablonun \xfcst sat\u0131r\u0131 Pazartesi-Cuma g\xfcnleri olmal\u0131d\u0131r.","Tabloyu kurduktan sonra kesin verilen \xf6nc\xfclleri yerle\u015ftir, ihtimalleri (Veya) tablonun alt\u0131na iki olas\u0131l\u0131k dal\u0131 olarak yaz!")
B.R1=new A.cT("fc_dgs_soz_2","Hemen \xd6ncesi / Sonras\u0131 \u0130fadesi","A, B'den hemen \xf6ncedir denirse AB blo\u011fu bozulamaz. A, B'den \xf6ncedir denirse araya ba\u015fka elemanlar girebilir.","DGS S\xf6zel Mant\u0131k","S\u0131ralama Sorular\u0131","Hemen \xf6ncesi: [A][B] biti\u015fik bloktur. Sadece \xf6ncesi: A ... B (arada eleman olabilir).","DGS s\xf6zel mant\u0131kta hemen kelimesi blok yapmay\u0131 zorunlu k\u0131lar; g\xf6zden ka\xe7arsa t\xfcm sorular hatal\u0131 \xe7\xf6z\xfcl\xfcr!")
B.R2=new A.cT("fc_dgs_say_4","\xd6r\xfcnt\xfc ve Periyodik Tekrarlar","Dizi belirli bir ad\u0131mda bir kendini tekrar ediyorsa periyot bulunur ve istenen ad\u0131m say\u0131s\u0131 periyoda b\xf6l\xfcn\xfcr.","DGS Say\u0131sal Mant\u0131k","Say\u0131 Dizileri","Pazartesiden itibaren 100 g\xfcn sonras\u0131: 100 mod 7 = 2 g\xfcn sonras\u0131 -> \xc7ar\u015famba.","DGS periyodik problemlerde mod\xfcler aritmetik kalan\u0131 aran\u0131lan g\xfcn ve durumu verir!")
B.R3=new A.cT("fc_dgs_geo_3","Benzerlik Oran\u0131 ve Alan \u0130li\u015fkisi (k\xb2)","\u0130ki \xfc\xe7gen aras\u0131ndaki benzerlik oran\u0131 k ise, \xe7evreleri oran\u0131 k, ALANLARI ORANI k\xb2 olur.","DGS Geometri","Benzerlik","Benzerlik oran\u0131 1/2 olan iki \xfc\xe7genin alanlar\u0131 oran\u0131 (1/2)\xb2 = 1/4't\xfcr.","Orta taban \xe7izildi\u011finde tepe \xfc\xe7genin alan\u0131 S ise alttaki yamu\u011fun alan\u0131 3S olur!")
B.R4=new A.cT("fc_dgs_soz_3","Kesin Do\u011fru vs Kesin Yanl\u0131\u015f","Her iki ihtimalde de de\u011fi\u015fmeyen bilgiler KES\u0130N DO\u011eRU'dur. \u0130ki ihtimalde de ger\xe7ekle\u015fmesi imkans\u0131z durumlar KES\u0130N YANLI\u015e't\u0131r.","DGS S\xf6zel Mant\u0131k","\xc7\u0131kar\u0131m Analizi","1. \u0130htimalde Ali 3. s\u0131rada, 2. \u0130htimalde de Ali 3. s\u0131rada ise Ali 3. s\u0131radad\u0131r kesin do\u011frudur.","\xd6SYM DGS'de genellikle 4 soruluk bir s\xf6zel mant\u0131k grubunun son iki sorusunu Hangisi kesinlikle do\u011frudur/yanl\u0131\u015ft\u0131r \u015feklinde sorar!")
B.R5=new A.cT("fc_dgs_tr_3","Dolaylama ve G\xfczel Adland\u0131rma","Dolaylama: Tek s\xf6zc\xfckle anlat\u0131labilecek kavram\u0131 birden \xe7ok s\xf6zc\xfckle anlatmakt\u0131r (Kara elmas: K\xf6m\xfcr, Yavru vatan: K\u0131br\u0131s). G\xfczel Adland\u0131rma: Korkulan veya naho\u015f durumlar\u0131 yumu\u015fatarak s\xf6ylemektir (\u0130nce hastal\u0131k: Verem).","DGS T\xfcrk\xe7e","S\xf6zc\xfckte Anlam","File bek\xe7isi (Kaleci), Bacas\u0131z sanayi (Turizm).","DGS s\xf6zc\xfckte anlamda mecaz-\u0131 m\xfcrsel (ad aktarmas\u0131) ve dolaylama s\u0131k\xe7a kar\u0131\u015ft\u0131r\u0131l\u0131r, dolaylamada kal\u0131pla\u015fm\u0131\u015f tamlama aran\u0131r!")
B.R6=new A.cT("fc_dgs_mat_5","Say\u0131 \xc7\xf6z\xfcmleme ve Fark Kural\u0131","AB = 10A + B, BA = 10B + A. AB - BA = 9(A - B). AB + BA = 11(A + B).","DGS Temel Matematik","Basamak Analizi","AB - BA = 36 ise 9(A - B) = 36 -> A - B = 4 bulunur.","ABC - CBA = 99(A - C) form\xfcl\xfcnde onlar basama\u011f\u0131ndaki B harfi fark i\u015fleminde birbirini yok eder!")
B.R7=new A.cT("fc_dgs_mat_1","Tek ve \xc7ift Say\u0131 Kurallar\u0131","T \xb1 T = \xc7, \xc7 \xb1 \xc7 = \xc7, T \xb1 \xc7 = T. T \xd7 T = T, T \xd7 \xc7 = \xc7, \xc7 \xd7 \xc7 = \xc7. \xc7arp\u0131m tek ise T\xdcM \xe7arpanlar tektir. \xc7arp\u0131m \xe7ift ise EN AZ B\u0130R \xe7arpan \xe7ifttir.","DGS Temel Matematik","Say\u0131 K\xfcmeleri","(a \xd7 b) + 1 = \xc7ift ise a \xd7 b = Tek olmal\u0131, dolay\u0131s\u0131yla hem a hem b tek olmak zorundad\u0131r.","\xd6SYM taban-tavan \xfcs sorular\u0131nda pozitif tam say\u0131 \xfcsler tekli\u011fi-\xe7iftli\u011fi DE\u011e\u0130\u015eT\u0130RMEZ (a\u207f ile a ayn\u0131 tekliktedir)!")
B.R8=new A.cT("fc_dgs_mat_9","K\xf6kl\xfc Say\u0131larda E\u015flenik","Paydadaki k\xf6kten kurtulmak i\xe7in ifade paydan\u0131n e\u015fleni\u011fi ile \xe7arp\u0131l\u0131r. \u221a(a) e\u015fleni\u011fi \u221a(a), (\u221aa - \u221ab) e\u015fleni\u011fi (\u221aa + \u221ab)'dir. \xc7arp\u0131m (a - b) olur.","DGS Temel Matematik","\xdcsl\xfc & K\xf6kl\xfc","1 / (\u221a3 - \u221a2) ifadesi (\u221a3 + \u221a2) ile \xe7arp\u0131l\u0131rsa payda 3 - 2 = 1 olur, sonu\xe7 \u221a3 + \u221a2 \xe7\u0131kar.","\xc7ift dereceli k\xf6klerin i\xe7i asla negatif olamaz (i\xe7erisi >= 0 olmal\u0131d\u0131r)!")
B.R9=new A.cT("fc_dgs_mat_2","Asall\u0131k ve Aralar\u0131nda Asall\u0131k","Sadece 1'e ve kendisine b\xf6l\xfcnebilen 1'den b\xfcy\xfck do\u011fal say\u0131lara asal say\u0131 denir. 2, tek \xe7ift asal say\u0131d\u0131r. 1'den ba\u015fka ortak pozitif b\xf6leni olmayan say\u0131lar aralar\u0131nda asald\u0131r.","DGS Temel Matematik","Asal Say\u0131lar","8 ve 15 asal de\u011fildir ancak 1'den ba\u015fka ortak b\xf6lenleri olmad\u0131\u011f\u0131 i\xe7in aralar\u0131nda asald\u0131r.","Ard\u0131\u015f\u0131k iki pozitif tam say\u0131 daima aralar\u0131nda asald\u0131r ve EBOB'lar\u0131 daima 1'dir!")
B.Ra=new A.cT("fc_dgs_say_2","Harfli Matematik ve Taban Mant\u0131\u011f\u0131","Kelimeler veya harfler rakamlarla e\u015fle\u015ftirildi\u011finde ayn\u0131 harf ayn\u0131 rakam\u0131 temsil eder. Toplama-\xe7arpma eldelerine dikkat edilir.","DGS Say\u0131sal Mant\u0131k","\u015eifreli \u0130\u015flemler","A + A = B ve B tek say\u0131 olamaz \xe7\xfcnk\xfc iki ayn\u0131 say\u0131n\u0131n toplam\u0131 \xe7ift olmal\u0131d\u0131r.","\xc7arpma i\u015fleminde son basamak kural\u0131 (\xf6rne\u011fin 5 ile \xe7arp\u0131mda son basamak 0 veya 5 olur) en kritik ipucudur!")
B.Rb=new A.cT("fc_dgs_prob_1","Ya\u015f Fark\u0131 Asla De\u011fi\u015fmez","\u0130ki ki\u015fi aras\u0131ndaki ya\u015f fark\u0131 zaman ge\xe7tik\xe7e daima sabit kal\u0131r. Ge\xe7en y\u0131l say\u0131s\u0131 herkesin ya\u015f\u0131na e\u015fit eklenir.","DGS Problemler","Ya\u015f Problemleri","Ali ile Veli aras\u0131ndaki ya\u015f fark\u0131 bug\xfcn 6 ise 15 y\u0131l sonra da 6'd\u0131r.","T ki\u015fi i\xe7in n y\u0131l sonra ya\u015flar\u0131 toplam\u0131 T \xd7 n kadar artar!")
B.Rc=new A.cT("fc_dgs_prob_3","Birim Zamanda Yap\u0131lan \u0130\u015f Prensibi","Bir i\u015fi A i\u015f\xe7isi x saatte, B i\u015f\xe7isi y saatte bitiriyorsa birlikte t saatte bitirme form\xfcl\xfc: (1/x + 1/y) \xd7 t = 1.","DGS Problemler","\u0130\u015f\xe7i Problemleri","Biri 6 g\xfcnde, di\u011feri 12 g\xfcnde bitirirse: (1/6 + 1/12) \xd7 t = 1 -> (3/12) \xd7 t = 1 -> t = 4 g\xfcn.","DGS i\u015f\xe7i sorular\u0131nda i\u015f\xe7i kapasitesi (h\u0131z\u0131) ile bitirme s\xfcresi ters orant\u0131l\u0131d\u0131r!")
B.Rd=new A.cT("fc_dgs_mat_7","0 < a < 1 (a\xb2 < a) Kural\u0131","Pozitif bir basit kesrin karesi daima kendisinden k\xfc\xe7\xfckt\xfcr (a\xb2 < a). \xd6rnek: a = 1/2 ise a\xb2 = 1/4 ve 1/4 < 1/2.","DGS Temel Matematik","E\u015fitsizlikler","x\xb2 < x e\u015fitsizli\u011fini sa\u011flayan x reel say\u0131lar\u0131 (0, 1) aral\u0131\u011f\u0131ndad\u0131r.","\xd6SYM bir soruda a\xb2 < a ifadesini veriyorsa a'n\u0131n (0, 1) aral\u0131\u011f\u0131nda oldu\u011funu gizlemi\u015ftir!")
B.Re=new A.cT("fc_dgs_prob_2","Kar\u015f\u0131la\u015fma ve Yeti\u015fme Form\xfclleri","Z\u0131t y\xf6nl\xfc (Kar\u015f\u0131la\u015fma): Yol = (V1 + V2) \xd7 t. Ayn\u0131 y\xf6nl\xfc (Yeti\u015fme): Yol = (V1 - V2) \xd7 t (V1 > V2).","DGS Problemler","H\u0131z - Hareket","Aralar\u0131nda 300 km olan iki ara\xe7 60 ve 40 km/s h\u0131zlarla birbirine do\u011fru gelirse t = 300 / (60+40) = 3 saatte kar\u015f\u0131la\u015f\u0131r.","T\xfcnel ve tren sorular\u0131nda toplam yol = Tren Boyu + T\xfcnel Boyu olarak al\u0131n\u0131r!")
B.Rf=new A.cT("fc_dgs_say_1","Daire Grafi\u011fi (360\xb0) ve Oranlama","Daire grafi\u011finin tamam\u0131 360\xb0 a\xe7\u0131d\u0131r ve %100'e denk gelir. 36\xb0 = %10, 18\xb0 = %5, 90\xb0 = 1/4 (%25).","DGS Say\u0131sal Mant\u0131k","Tablo & Grafik","Merkez a\xe7\u0131s\u0131 72\xb0 olan \xfcr\xfcn \xfcretimin 72/360 = 1/5'ini (%20'sini) olu\u015fturur.","DGS grafik sorular\u0131nda b\xfcy\xfck say\u0131larla u\u011fra\u015fmak yerine a\xe7\u0131lar\u0131n EBOB'u ile sadele\u015ftirip k katsay\u0131s\u0131 ver!")
B.Rg=new A.cT("fc_dgs_prob_5","Kar\u0131\u015f\u0131m Y\xfczdesi Denklem Form\xfcl\xfc","(1. Miktar \xd7 1. Y\xfczde) + (2. Miktar \xd7 2. Y\xfczde) = Toplam Miktar \xd7 Son Y\xfczde.","DGS Problemler","Kar\u0131\u015f\u0131m Problemleri","20 kg %30'luk tuzlu su ile 30 kg %40'l\u0131k kar\u0131\u015ft\u0131r\u0131l\u0131rsa: (20\xd730 + 30\xd740) / 50 = (600 + 1200) / 50 = %36.","Kar\u0131\u015f\u0131ma saf su eklenirse tuz y\xfczdesi 0, saf tuz eklenirse tuz y\xfczdesi 100 al\u0131n\u0131r!")
B.Rh=new A.cT("fc_dgs_tr_1","Ana D\xfc\u015f\xfcnce Belirleme","Yazar\u0131n okuyucuya vermek istedi\u011fi as\u0131l mesaj, \xf6\u011f\xfct veya temel iletidir. Genellikle k\u0131sacas\u0131, \xf6zetle, oysa, as\u0131l \xf6nemli olan gibi ba\u011flay\u0131c\u0131 s\xf6zc\xfcklerden sonra vurgulan\u0131r.","DGS T\xfcrk\xe7e","Paragrafta Anlam","Paragraf\u0131n b\xfct\xfcn\xfc tek bir yarg\u0131 c\xfcmlesiyle \xf6zetlenebiliyorsa o c\xfcmle ana fikirdir.","Ana d\xfc\u015f\xfcnce sorular\u0131nda par\xe7ada ge\xe7se bile yan ayr\u0131nt\u0131lara tak\u0131lma, yazar\u0131n savundu\u011fu temel teze odaklan!")
B.Ri=new A.cT("fc_dgs_mat_8","Mutlak De\u011fer \xd6zellikleri","|x| >= 0 daima. |x| = a (a >= 0) ise x = a veya x = -a. |x| < a ise -a < x < a. |x| > a ise x > a veya x < -a.","DGS Temel Matematik","Mutlak De\u011fer","|2x - 1| = 5 ise 2x - 1 = 5 (x=3) veya 2x - 1 = -5 (x=-2).","Mutlak de\u011ferli denklemlerde mutlak de\u011ferin i\xe7i s\u0131f\u0131ra e\u015fitlenerek kritik noktalar bulunur!")
