B.a9V=new A.hZ(["Bu konuyu seninle kar\u015f\u0131l\u0131kl\u0131 tart\u0131\u015ft\u0131k.",'"kar\u015f\u0131l\u0131kl\u0131" s\xf6zc\xfc\u011f\xfc gereksizdir; "tart\u0131\u015fmak" zaten kar\u015f\u0131l\u0131kl\u0131 yap\u0131l\u0131r.',B.a1G,'Gereksiz s\xf6zc\xfck kullan\u0131m\u0131 durulu\u011fu bozar; "tart\u0131\u015fmak" eylemi zaten kar\u015f\u0131l\u0131kl\u0131 ger\xe7ekle\u015fir.'])
B.XL=s(["Gereksiz yard\u0131mc\u0131 eylem kullan\u0131lm\u0131\u015ft\u0131r.","S\xf6zc\xfck yanl\u0131\u015f yerde kullan\u0131lm\u0131\u015ft\u0131r.","Nesne eksikli\u011fi vard\u0131r.","Zarf t\xfcmleci gereksizdir."],t.s)
B.aa1=new A.hZ(["\xd6\u011frencilerin \xe7o\u011fu derse zaman\u0131nda geldi, ancak hi\xe7biri \xf6devini getirmemi\u015fler.",'Belgisiz zamir "hi\xe7biri" \xf6zne oldu\u011funda y\xfcklem tekil ("getirmemi\u015f") olmal\u0131d\u0131r.',B.XL,'"Hi\xe7biri, herkes, kimse" gibi belgisiz \xf6znelerle y\xfcklem tekil \xe7ekimlenir.'])
B.ZR=s(["\xc7eli\u015fen s\xf6zc\xfckler bir arada kullan\u0131lm\u0131\u015ft\u0131r.","\xd6zne eksikli\u011fi anlat\u0131m\u0131 bozmu\u015ftur.","Dolayl\u0131 t\xfcmle\xe7 eksikli\u011fi vard\u0131r.","Edat yanl\u0131\u015f kullan\u0131lm\u0131\u015ft\u0131r."],t.s)
B.aa7=new A.hZ(["\u0130lk kez yap\u0131lan bu yar\u0131\u015fmaya kat\u0131l\u0131m olduk\xe7a azd\u0131 ve kimse dereceye giremedi.",'Mant\u0131k hatas\u0131 yoktur; ancak "A\u015fa\u011f\u0131daki c\xfcmlelerin hangisinde anlat\u0131m bozuklu\u011fu vard\u0131r?" kal\u0131b\u0131nda do\u011fru yarg\u0131 aran\u0131yorsa dikkat edilmelidir.',B.ZR,"C\xfcmle dil bilgisi ve anlam bak\u0131m\u0131ndan tutarl\u0131d\u0131r."])
B.a0M=s(["\xd6zne-y\xfcklem uyumu bozulmu\u015ftur.","Tamlayan eki eksiktir.","Ek eylem yanl\u0131\u015f kullan\u0131lm\u0131\u015ft\u0131r.","\xc7at\u0131 uyu\u015fmazl\u0131\u011f\u0131 vard\u0131r."],t.s)
B.a9X=new A.hZ(["Eminim ki bu ak\u015fam mutlaka bize u\u011frayabilir.",'"Eminim/mutlaka" (kesinlik) ile "-ebilir" (olas\u0131l\u0131k) anlamca \xe7eli\u015fmektedir.',B.a0M,"Kesinlik bildiren zarflar ile olas\u0131l\u0131k bildiren kipler ayn\u0131 c\xfcmlede \xe7eli\u015fki yarat\u0131r."])
B.WL=s(["Gereksiz ek kullan\u0131lm\u0131\u015ft\u0131r.","Nesne eksikli\u011fi vard\u0131r.","Deyim yanl\u0131\u015f anlamda kullan\u0131lm\u0131\u015ft\u0131r.","Ba\u011fla\xe7 yanl\u0131\u015f yere konmu\u015ftur."],t.s)
B.a9Z=new A.hZ(["\xc7ok ba\u015f\u0131m a\u011fr\u0131d\u0131\u011f\u0131 i\xe7in toplant\u0131ya kat\u0131lamad\u0131m.",'S\xf6zc\xfc\u011f\xfcn yanl\u0131\u015f yerde kullan\u0131m\u0131: "Ba\u015f\u0131m \xe7ok a\u011fr\u0131d\u0131\u011f\u0131 i\xe7in..." olmal\u0131d\u0131r.',B.WL,'"\xc7ok" zarf\u0131 "ba\u015f\u0131m" ismini de\u011fil, "a\u011fr\u0131d\u0131\u011f\u0131" fiilimsisini nitelemelidir.'])
B.a1h=s(["\xd6zne eksikli\u011fi vard\u0131r.","Yard\u0131mc\u0131 fiil gereksizdir.","Tamlama yanl\u0131\u015f\u0131 vard\u0131r.","E\u015f anlaml\u0131 s\xf6zc\xfckler bir arada kullan\u0131lm\u0131\u015ft\u0131r."],t.s)
B.aa6=new A.hZ(["B\u0131rak\u0131n doktor olmay\u0131, i\u011fne bile yapamaz o.",'S\u0131ralama / mant\u0131k hatas\u0131: "B\u0131rak\u0131n i\u011fne yapmay\u0131, doktor bile olamaz" \u015feklinde d\xfczeltilmelidir.',B.a1h,"Basit olandan zor olana do\u011fru mant\u0131ksal s\u0131ralama yap\u0131lmal\u0131d\u0131r."])
