B.aa3=new A.hZ(["Diyelim ki s\u0131navda hi\xe7 beklemedi\u011fin bir konudan \xfc\xe7 soru birden geldi.","Varsay\u0131m c\xfcmlesi",B.a0Y,'"Diyelim ki" ifadesi ger\xe7ekle\u015fmemi\u015f bir durumu ge\xe7ici olarak olmu\u015f gibi kabul etmeyi (varsay\u0131m) bildirir.'])
